const h = await require('node:fs').promises.open('/data/digits.txt', 'r')
const parts = [Buffer.alloc(3), Buffer.alloc(4)]
const { bytesRead } = await h.readv(parts)
const next = await h.read(Buffer.alloc(1), 0, 1, null)
console.log(bytesRead, parts[0].toString(), parts[1].toString(), next.buffer.toString())
await h.close()

const h = await require('node:fs').promises.open('/data/digits.txt', 'r')
const tail = [Buffer.alloc(2), Buffer.alloc(5)]
const { bytesRead } = await h.readv(tail, 6)
const next = await h.read(Buffer.alloc(1), 0, 1, null)
console.log(bytesRead, Buffer.concat(tail).subarray(0, bytesRead).toString(), next.buffer.toString())
await h.close()
